{
  "tools": [
    {
      "name": "add_component",
      "title": "Add Component",
      "toolset": "scene",
      "description": "Add a component to a game object, optionally setting its properties in the same call. The user can undo this. Returns the component's id.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "The game object's id, from scene_tree or find_game_objects."
          },
          "type": {
            "type": "string",
            "description": "The component type name, e.g. 'ModelRenderer'. get_component_type documents what exists."
          },
          "properties": {
            "type": "object",
            "description": "Optional json object of property values, e.g. {\"LightColor\": \"1,0.8,0.6,1\", \"Radius\": 512}."
          }
        },
        "required": [
          "id",
          "type"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Id": {
            "type": "string"
          },
          "Type": {
            "type": "string"
          },
          "GameObject": {
            "type": "string"
          }
        },
        "required": []
      }
    },
    {
      "name": "bridge_scatter_props",
      "title": "Native Scatter Props",
      "toolset": "bridge_helpers",
      "description": "Scatter model props with a repeatable seed, optional ground snapping, rotation, scaling and grouping. Requires stopped play mode. Uses the existing Bridge helper's scene and undo behaviour.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "model": {
            "type": "string",
            "description": "Project-relative model path, as returned by asset_search."
          },
          "center": {
            "type": "string",
            "description": "World-space centre as x,y,z, in Source units."
          },
          "radius": {
            "type": "number",
            "description": "Finite, nonnegative scatter radius in Source units.",
            "default": 256
          },
          "count": {
            "type": "integer",
            "description": "Number of props, from 1 to 300.",
            "default": 10
          },
          "seed": {
            "type": "integer",
            "description": "Nonnegative seed for repeatable placement.",
            "default": 1
          },
          "snapToGround": {
            "type": "boolean",
            "description": "Trace downward to place each prop on the ground.",
            "default": true
          },
          "randomYaw": {
            "type": "boolean",
            "description": "Randomise each prop's yaw.",
            "default": true
          },
          "scaleMin": {
            "type": "number",
            "description": "Positive minimum scale.",
            "default": 1
          },
          "scaleMax": {
            "type": "number",
            "description": "Maximum scale, at least scaleMin.",
            "default": 1
          },
          "group": {
            "type": "boolean",
            "description": "Parent the props under a new group object.",
            "default": true
          },
          "name": {
            "type": "string",
            "description": "Name prefix for the created objects.",
            "default": "Prop"
          }
        },
        "required": [
          "model",
          "center"
        ]
      }
    },
    {
      "name": "camera_screenshot",
      "title": "Camera Screenshot",
      "toolset": "scene",
      "description": "Render a camera in the scene and return it as an image. Give any CameraComponent's id or its game object's id, or nothing for the scene's main camera. Works in edit and play mode - editor_camera_screenshot shows the editor viewport instead.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "camera": {
            "type": "string",
            "description": "A CameraComponent id or its game object's id. Empty uses the scene's main camera."
          },
          "width": {
            "type": "integer",
            "description": "Image width in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 1280
          },
          "height": {
            "type": "integer",
            "description": "Image height in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 720
          },
          "includeUi": {
            "type": "boolean",
            "description": "Include any UI the camera renders.",
            "default": true
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "close_scene",
      "title": "Close Scene",
      "toolset": "scenefile",
      "description": "Close a scene tab. Refuses to throw away unsaved work unless you say so.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "scene": {
            "type": "string",
            "description": "Scene name or resource path. Empty for the active one."
          },
          "discardChanges": {
            "type": "boolean",
            "description": "Close even if the scene has unsaved changes.",
            "default": false
          }
        },
        "required": []
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Active": {
            "type": "string"
          },
          "ActivePath": {
            "type": "string"
          },
          "Open": {
            "type": "array",
            "items": {
              "type": "string"
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "create_game_object",
      "title": "Create Game Object",
      "toolset": "scene",
      "description": "Create a game object in the active scene - empty or from a prefab, optionally with components. For putting a model in the scene, spawn_model is quicker. The user can undo this. Returns the new object's id for the other scene tools.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Name for the new object. Empty picks a sensible default."
          },
          "parent": {
            "type": "string",
            "description": "Parent game object id. Empty parents to the scene root."
          },
          "prefab": {
            "type": "string",
            "description": "Prefab asset path to instantiate, from asset_search."
          },
          "position": {
            "type": "string",
            "description": "World position as 'x,y,z'. Default origin."
          },
          "angles": {
            "type": "string",
            "description": "Rotation as 'pitch,yaw,roll'."
          },
          "scale": {
            "type": "string",
            "description": "Scale as 'x,y,z', or a single number for uniform."
          },
          "components": {
            "type": "string",
            "description": "Comma separated component type names to add, e.g. 'ModelRenderer,BoxCollider'."
          }
        },
        "required": []
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Id": {
            "type": "string"
          },
          "Name": {
            "type": "string"
          },
          "Position": {
            "type": "string"
          },
          "Components": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "string"
                },
                "Type": {
                  "type": "string"
                },
                "GameObject": {
                  "type": "string"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "delete_game_object",
      "title": "Delete Game Object",
      "toolset": "scene",
      "description": "Delete a game object and its children. The user can undo this.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "The game object's id, from scene_tree or find_game_objects."
          }
        },
        "required": [
          "id"
        ]
      }
    },
    {
      "name": "editor_camera_screenshot",
      "title": "Editor Camera Screenshot",
      "toolset": "scene",
      "description": "Render what the editor scene camera sees and return it as an image - see the scene the way the viewport does. Move the view first with set_editor_camera.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "width": {
            "type": "integer",
            "description": "Image width in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 1280
          },
          "height": {
            "type": "integer",
            "description": "Image height in pixels.",
            "minimum": 16,
            "maximum": 4096,
            "default": 720
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "editor_status",
      "title": "Get Editor Status",
      "toolset": "editor",
      "description": "Get the current state of the editor - engine version, which project is open, the active scene and whether it has unsaved changes, whether play mode is running or paused, how many tools are registered, the directory paths that matter (logs, project code and assets), and the state of the code compiler. Check IsCompiling/LastCompileSucceeded here after editing code instead of relying on read_console - a successful compile can scroll out of view or be mistaken for the last failure you saw.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "EngineVersion": {
            "type": "string"
          },
          "Project": {
            "type": "string"
          },
          "ProjectTitle": {
            "type": "string"
          },
          "ActiveScene": {
            "type": "string"
          },
          "ActiveScenePath": {
            "type": "string"
          },
          "SceneHasUnsavedChanges": {
            "type": "boolean"
          },
          "IsPlaying": {
            "type": "boolean"
          },
          "IsPaused": {
            "type": "boolean"
          },
          "ToolCount": {
            "type": "integer"
          },
          "IsCompiling": {
            "type": "boolean"
          },
          "LastCompileSucceeded": {
            "type": "boolean"
          },
          "LastCompileErrors": {
            "type": "integer"
          },
          "Paths": {
            "type": "object",
            "properties": {
              "Engine": {
                "type": "string"
              },
              "Logs": {
                "type": "string"
              },
              "ProjectRoot": {
                "type": "string"
              },
              "ProjectSettings": {
                "type": "string"
              }
            },
            "required": []
          }
        },
        "required": []
      }
    },
    {
      "name": "find_game_objects",
      "title": "Find Game Objects",
      "toolset": "scene",
      "description": "Search a scene's game objects by name substring, component type and/or tag. All filters are optional and combine - empty filters list everything. Returns each match with its hierarchy path and id.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "Case insensitive substring of the object's name."
          },
          "component": {
            "type": "string",
            "description": "Case insensitive substring of a component type name the object must have."
          },
          "tag": {
            "type": "string",
            "description": "A tag the object must have."
          },
          "scene": {
            "type": "string",
            "description": "Scene name or resource path from list_scenes. Empty for the active scene."
          },
          "limit": {
            "type": "integer",
            "description": "How many matches to return.",
            "minimum": 1,
            "maximum": 500,
            "default": 100
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Total": {
            "type": "integer",
            "description": "How many matched in total, beyond what's shown."
          },
          "Results": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Name": {
                  "type": "string"
                },
                "Id": {
                  "type": "string"
                },
                "Path": {
                  "type": "string",
                  "description": "The object's place in the hierarchy, like 'Map/Props/Barrel'."
                },
                "Enabled": {
                  "type": "boolean"
                },
                "Components": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  }
                }
              },
              "required": []
            }
          },
          "Truncated": {
            "type": "boolean",
            "description": "True when the scene was too big to finish searching."
          }
        },
        "required": []
      }
    },
    {
      "name": "get_editor_camera",
      "title": "Get Editor Camera",
      "toolset": "scene",
      "description": "The editor scene camera's transform - where the scene viewport is looking from. Position, angles (pitch yaw roll) and field of view.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Position": {
            "type": "string"
          },
          "Angles": {
            "type": "string"
          },
          "FieldOfView": {
            "type": "number"
          }
        },
        "required": []
      }
    },
    {
      "name": "get_game_object",
      "title": "Get Game Object",
      "toolset": "scene",
      "description": "Everything about one game object - enabled state, tags, world transform, parent, children, and its components. Set includeComponentProperties to also get every component's serialized properties.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "The game object's id, from scene_tree or find_game_objects."
          },
          "includeComponentProperties": {
            "type": "boolean",
            "description": "Include the full serialized properties of every component, not just their types.",
            "default": false
          }
        },
        "required": [
          "id"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Scene": {
            "type": "string"
          },
          "Name": {
            "type": "string"
          },
          "Id": {
            "type": "string"
          },
          "Enabled": {
            "type": "boolean"
          },
          "ActiveInHierarchy": {
            "type": "boolean"
          },
          "Tags": {
            "type": "array",
            "items": {
              "type": "string"
            }
          },
          "Parent": {
            "type": "object",
            "properties": {
              "Id": {
                "type": "string"
              },
              "Name": {
                "type": "string"
              }
            },
            "required": [],
            "description": "The parent. Null when parented to the scene root."
          },
          "WorldPosition": {
            "type": "string"
          },
          "WorldRotation": {
            "type": "string"
          },
          "WorldScale": {
            "type": "string"
          },
          "Components": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Type": {
                  "type": "string"
                },
                "Id": {
                  "type": "string"
                },
                "Enabled": {
                  "type": "boolean"
                },
                "Properties": {
                  "description": "The serialized properties. Null unless includeComponentProperties was set."
                }
              },
              "required": []
            }
          },
          "Children": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                },
                "Enabled": {
                  "type": "boolean"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "get_selection",
      "title": "Get Selection",
      "toolset": "scene",
      "description": "What's selected in the editor - the game objects and components the user (or you) has picked.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "GameObjects": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "string"
                },
                "Name": {
                  "type": "string"
                }
              },
              "required": []
            }
          },
          "Components": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Id": {
                  "type": "string"
                },
                "Type": {
                  "type": "string"
                },
                "GameObject": {
                  "type": "string"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "instance_status",
      "title": "Status",
      "toolset": "instance",
      "description": "Get this process's PID, kind, project, engine version, active scene, play state and session exchange directory. Files in the exchange directory are retained after disconnect.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "list_scenes",
      "title": "List Scenes",
      "toolset": "scene",
      "description": "List the scenes open in the editor - name, resource path, type (scene, prefab or the running game session), whether it's the active tab, unsaved changes, and root object count.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Scenes": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Name": {
                  "type": "string"
                },
                "ResourcePath": {
                  "type": "string"
                },
                "Type": {
                  "type": "string",
                  "description": "Scene, Prefab, or Game for the running session."
                },
                "IsActive": {
                  "type": "boolean"
                },
                "HasUnsavedChanges": {
                  "type": "boolean"
                },
                "RootObjectCount": {
                  "type": "integer"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "open_scene",
      "title": "Open Scene",
      "toolset": "scenefile",
      "description": "Open a scene from the asset system and make it the active tab. Already open scenes are just brought to the front. Play mode has to be stopped first - play_start then runs this scene.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string",
            "description": "Scene asset path, like \"scenes/menu-main.scene\". asset_search finds them."
          }
        },
        "required": [
          "path"
        ]
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Active": {
            "type": "string"
          },
          "ActivePath": {
            "type": "string"
          },
          "Open": {
            "type": "array",
            "items": {
              "type": "string"
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "perf_rendering",
      "title": "Rendering",
      "toolset": "perf",
      "description": "Rendering detail for the last frame: which renderer drew it, resolution and AA, the rendering issues the performance hub flags (draw calls, batching, texture pool), every scene system counter (draws, triangles, batches, material changes, culling, lights and shadows, texture pool, device report), the managed renderer's phases and draws when it rendered, and the active camera's post-processing layers.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "play_start",
      "title": "Play Start",
      "toolset": "play",
      "description": "Start playing the current scene, like pressing the editor's play button. Startup errors land in the console - check read_console if things look wrong.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "IsPlaying": {
            "type": "boolean"
          },
          "IsPaused": {
            "type": "boolean"
          },
          "Scene": {
            "type": "string",
            "description": "The scene being played. Null when not playing."
          }
        },
        "required": []
      }
    },
    {
      "name": "redo",
      "title": "Redo",
      "toolset": "scene",
      "description": "Redo the last undone edit in the active scene.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      }
    },
    {
      "name": "remove_component",
      "title": "Remove Component",
      "toolset": "scene",
      "description": "Remove a component. Give the component's id, or its game object's id plus a type name. The user can undo this. Removal applies at the end of the frame, so reading the object in the same batch still shows it.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "The component's id, or its game object's id."
          },
          "type": {
            "type": "string",
            "description": "The component type to remove, when id is a game object."
          }
        },
        "required": [
          "id"
        ]
      }
    },
    {
      "name": "run_csharp",
      "title": "Run",
      "toolset": "instance",
      "description": "Run a trusted C# method body on the engine main thread in game scope. Supply code OR an absolute path to a UTF-8 script file. Supports await and return (object); System, System.Linq, System.Threading, System.Threading.Tasks and Sandbox are imported. Parameters exchangeDirectory and cancellationToken are available. Example: return Game.ActiveScene?.Name; Engine/editor APIs are available, with editor types fully qualified. This has full local process privileges, may mutate live state, and does not create undo steps. Cancellation is cooperative: check cancellationToken in loops. Discover this tool through search_tools.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "code": {
            "type": "string",
            "description": "C# method body to execute. Mutually exclusive with path."
          },
          "path": {
            "type": "string",
            "description": "Absolute path to a UTF-8 C# method body, usually in the session exchange directory."
          }
        },
        "required": []
      }
    },
    {
      "name": "save_scene",
      "title": "Save Scene",
      "toolset": "scene",
      "description": "Save the active scene to its file.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Saved": {
            "type": "string"
          },
          "HasUnsavedChanges": {
            "type": "boolean"
          }
        },
        "required": []
      }
    },
    {
      "name": "scene_trace",
      "title": "Scene Trace",
      "toolset": "scene",
      "description": "Trace a ray through the active scene's physics and report what it hits - find the floor, check line of sight, probe where something can be placed.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "from": {
            "type": "string",
            "description": "Ray start as 'x,y,z'."
          },
          "to": {
            "type": "string",
            "description": "Ray end as 'x,y,z'."
          }
        },
        "required": [
          "from",
          "to"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Hit": {
            "type": "boolean",
            "description": "Whether the trace hit anything."
          },
          "StartedSolid": {
            "type": "boolean",
            "description": "Whether the trace started inside something solid."
          },
          "EndPosition": {
            "type": "string",
            "description": "Where the trace ended - the hit point, or the requested end on a miss."
          },
          "Normal": {
            "type": "string",
            "description": "The hit surface normal."
          },
          "Fraction": {
            "type": "number",
            "description": "How far along the ray the hit was, 0 to 1."
          },
          "Distance": {
            "type": "number",
            "description": "How far the trace travelled, in units."
          },
          "GameObject": {
            "type": "object",
            "properties": {
              "Id": {
                "type": "string"
              },
              "Name": {
                "type": "string"
              }
            },
            "required": [],
            "description": "The game object hit. Null on a miss."
          },
          "Component": {
            "type": "string",
            "description": "The component type hit. Null on a miss."
          }
        },
